{
  "candidates": [
    {
      "title": "Cathedral Breached",
      "segments": [
        {
          "start_id": "E041-B0026",
          "end_id": "E041-B0053"
        }
      ],
      "hook": "At E041-B0026 (00:41.00), Catherine projects derisively to the cathedral, 'Lady Juliana Ashcroft. Look around,' publicly parading a chained captive before high society.",
      "cliffhanger": "At E041-B0053, silhouetted armed figures emerge through the pulverized cathedral doors while Juliana's face fills with breathless awe, leaving unresolved who stormed the wedding and whether she will be rescued.",
      "standalone_context": "A cruel bride pauses her lavish nuptials to publicly humiliate a woman brought in chains, only for a massive detonation to demolish the church entrance as armed forces invade.",
      "why_it_works": "The sharp tonal pivot from aristocratic cruelty to explosive violence instantly hooks scrolling viewers and sets up an epic rescue.",
      "concerns": "The identities of the armed invaders remain obscured by smoke at the cut."
    },
    {
      "title": "The True Duke Returns",
      "segments": [
        {
          "start_id": "E042-B0009",
          "end_id": "E042-B0036"
        }
      ],
      "hook": "At E042-B0009 and E042-B0010 (00:18.00), Rupert charges down the altar steps screaming frantically, 'Guards! Arrest this imposter!'",
      "cliffhanger": "At E042-B0036, Alexander rests his hand on his sabre and warns the trembling Rupert, 'And now, Rupert... we settle what you stole,' leaving Rupert cornered and awaiting retribution.",
      "standalone_context": "A frantic usurper attempts to arrest an intruder, but his royal guards refuse to obey because the newcomer is the presumed-dead rightful Duke, recognized and confirmed by his own mother.",
      "why_it_works": "The guards' immediate refusal to obey Rupert's command creates instant dramatic reversal, building momentum to an emotional maternal reunion and a promise of vengeance.",
      "concerns": "None identified."
    },
    {
      "title": "Treason in the Chapel",
      "segments": [
        {
          "start_id": "E043-B0056",
          "end_id": "E043-B0087"
        }
      ],
      "hook": "At E043-B0056 and E043-B0057 (01:09.00), Alexander towers over Rupert and roars accusations across the hall: 'You sold my men to the enemy.'",
      "cliffhanger": "At E043-B0087, Lord Sterling throws open the chapel side exit only to be trapped by a police constable asking, 'Going somewhere, Lord Sterling?', cutting to black on his terrified face.",
      "standalone_context": "Alexander confronts Rupert with Crown military intelligence proving Rupert and Sterling committed wartime treason to steal his ducal title, causing Rupert to betray Sterling, who tries to flee.",
      "why_it_works": "Shocking battlefield betrayal and official documentation force the conspirators against each other, ending on a thrilling intercepted escape.",
      "concerns": "Lord Sterling is not extensively introduced before his panicked flight, though his complicity is immediately clear."
    },
    {
      "title": "The Duke's Choice",
      "segments": [
        {
          "start_id": "E044-B0017",
          "end_id": "E044-B0053"
        }
      ],
      "hook": "At E044-B0017 and E044-B0018 (00:25.20), Catherine abandons Rupert and rushes toward Alexander in her bridal gown, weeping, 'Alexander... I thought you had died.'",
      "cliffhanger": "At E044-B0053, Alexander bypasses the aristocratic bride and strides straight to the chained Juliana at the door, leaving Catherine gasping in horrified disbelief: 'Her?!'",
      "standalone_context": "The bride tries to salvage her position by claiming enduring love for the returning Duke, but he coldly rejects her superficial loyalty and walks toward a captive woman standing in chains.",
      "why_it_works": "A scathing romantic rejection subverts expectations when the Duke ignores the glamorous bride in favor of a chained outcast.",
      "concerns": "None identified."
    },
    {
      "title": "Unlawful Duchess",
      "segments": [
        {
          "start_id": "E045-B0044",
          "end_id": "E045-B0073"
        }
      ],
      "hook": "At E045-B0044 and E045-B0045 (01:02.60), Alexander condemns Catherine before the congregation: 'You hurt the two women who mattered most to me: my mother, and my wife.'",
      "cliffhanger": "At E045-B0073, the High Priest rules that Juliana is not Alexander's lawful wife for lack of a Crown license, leaving Juliana in terror while Catherine flashes a venomous smile.",
      "standalone_context": "Alexander stuns high society by presenting Juliana as his lawful Duchess, but the High Priest storms in with armed officers and revokes the union's legal standing on the spot.",
      "why_it_works": "A soaring public vindication is suddenly sabotaged by ecclesiastical law, instantly shifting the advantage back to the villain.",
      "concerns": "None identified."
    }
  ]
}
